curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=cart&tags=%7B%22error%22%3A%22true%22%7D&lookback=6h&limit=3' 2>&1 | python3 -c "
import sys,json
d=json.load(sys.stdin)
for t in d.get('data',[])[:3]:
    for s in t['spans']:
        tags={x['key']:x['value'] for x in s['tags']}
        if tags.get('error')=='true' or tags.get('otel.status_code')=='ERROR':
            print('trace',t['traceID'][:16],'op=',s['operationName'])
            for l in s.get('logs',[]):
                for f in l['fields']:
                    if f['key'] in ('event','exception.message','exception.type','message'):
                        print('   ',f['key'],'=',str(f['value'])[:160])
            print('   status_msg=',tags.get('otel.status_description') or tags.get('error.message'))
"

curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=cart&tags=%7B%22error%22%3A%22true%22%7D&lookback=6h&limit=5' 2>&1 | python3 -c "
import sys,json
d=json.load(sys.stdin)
data=d.get('data',[])
print('n_traces=',len(data))
seen=set()
for t in data:
    for s in t['spans']:
        tags={x['key']:x.get('value') for x in s['tags']}
        msg=tags.get('otel.status_description') or tags.get('exception.message')
        for l in s.get('logs',[]):
            for f in l['fields']:
                if f['key'] in ('exception.message','exception.type','exception.stacktrace'):
                    v=str(f['value'])[:200]
                    if v not in seen:
                        seen.add(v); print(f['key'],':',v)
        if msg: 
            k='STATUS:'+str(msg)[:200]
            if k not in seen: seen.add(k); print(k)
"
